var t=`0173-polenta-con-funghi`;var n=`world-0173`;var o=`IT`;var a=`southern-europe`;var s=4;var r=46;var g={en:`Polenta con Funghi`,ua:`Полента з грибами`};var m={en:`A classic dish from Italy, featuring button mushroom, garlic, polenta, parmigiano reggiano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: печериця, часник, полента, парміджано реджано. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`button-mushroom`,420,`g`],[`garlic`,3,`clove`],[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 7 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 7 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:7,i:[[`water`,1e3,`ml`],[`table-salt`,4,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 26 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 26 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:26,i:[[`polenta`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,55,`g`],[`parmigiano-reggiano`,85,`g`],[`parsley`,20,`g`]]}];var u={slug:t,id:n,country:`IT`,region:a,servings:4,minutes:46,title:g,text:m,steps:l};export{o as country,u as default,n as id,r as minutes,a as region,s as servings,t as slug,l as steps,m as text,g as title};